insert into public.announcements (id, title, message, priority, active, posted_at) values
  ('a0000000-0000-4000-8000-000000000001', 'Pre-emptive evacuation for low-lying puroks', 'Families in flood-prone areas are advised to proceed to the nearest open evacuation center. Bring IDs, medicine, and water.', 'urgent', true, now() - interval '120 minutes'),
  ('a0000000-0000-4000-8000-000000000002', 'Covered Court is nearly full', 'New arrivals are encouraged to go to Pangabugan Elementary School or the Day Care Center.', 'warning', true, now() - interval '40 minutes'),
  ('a0000000-0000-4000-8000-000000000003', 'Relief goods distribution at 12:00 NN', 'Family heads, please line up at the center registration desk with your family number.', 'info', true, now() - interval '155 minutes')
