insert into public.policies (id, type, title, summary, legal_basis, status) values
  ('P-01', 'Ordinance', 'DRAFT Barangay Ordinance No. ___, Series of 2026: Adopting the Community Evacuation Center Management System', 'Adopts the system as the official record of evacuees, evacuation centers, supplies, and announcements during disasters. Designates the BDRRM Committee as system administrator and requires all evacuation center staff to record evacuees through the system.', 'RA 10121 (Philippine DRRM Act of 2010); RA 10173 (Data Privacy Act of 2012)', 'Draft (sample)'),
  ('P-02', 'Policy', 'Registration of evacuees', 'Every family is registered upon arrival at an evacuation center, with the head of family as the main contact. Each member is listed with age, sex, relationship, and vulnerable group, if any.', 'RA 10121', 'Draft (sample)'),
  ('P-03', 'Policy', 'Priority for vulnerable groups', 'Senior citizens, persons with disability, pregnant and lactating women, infants, and children receive priority in space allocation, relief distribution, and health checks.', 'RA 10821 (Children''s Emergency Relief and Protection Act); RA 9994 (Expanded Senior Citizens Act of 2010); RA 7277 (Magna Carta for Disabled Persons)', 'Draft (sample)'),
  ('P-04', 'Rule', 'Evacuation center house rules', 'Follow the instructions of center coordinators. Keep your assigned area clean. No alcohol, gambling, or weapons. Quiet hours from 9:00 PM to 5:00 AM. Report illness or injury to the health desk immediately.', 'Barangay policy (to be confirmed)', 'Draft (sample)'),
  ('P-05', 'Policy', 'Relief distribution', 'Relief goods are released per family to the head of family or an authorized adult member, and every release is recorded in the distribution list with the receiver''s signature.', 'RA 10121', 'Draft (sample)'),
  ('P-06', 'Policy', 'Health records and data privacy', 'Health information of evacuees is sensitive personal information. Only health workers and the system administrator may view or update it, and it is used only to provide assistance. It is never shown on the public website.', 'RA 10173 (Data Privacy Act of 2012)', 'Draft (sample)'),
  ('P-07', 'Policy', 'Evacuation center capacity', 'A center is marked Nearly Full at 80% of capacity and Full at 100%. New arrivals at a full center are directed to the nearest open center.', 'Barangay policy (to be confirmed)', 'Draft (sample)')
